// "A customer has orders", so the aggregate holds all of them
public sealed class Customer
{
    public CustomerId Id { get; init; }
    public string Phone { get; private set; } = "";
    public List<Address> Addresses { get; } = [];
    public List<Order> Orders { get; } = []; // every order, for years
    public int Version { get; private set; } // checked on every save

    public void PlaceOrder(Order order) { Orders.Add(order); Version++; }
    public void ChangePhone(string phone) { Phone = phone; Version++; }
}
// Checkout loads years of orders to add one, and a phone change
// at the same moment makes one of the two saves fail

namespace Sales;
// Order is its own aggregate and guards its own rules
public sealed class Order
{
    private readonly List<OrderLine> _lines;
    public OrderId Id { get; } = OrderId.New();
    public CustomerId CustomerId { get; } // reference by identity
    public IReadOnlyList<OrderLine> Lines => _lines;

    public Order(CustomerId customerId, List<OrderLine> lines)
    {
        if (lines.Count == 0)
            throw new ArgumentException("An order needs lines");
        CustomerId = customerId;
        _lines = [.. lines];
    }
}

// Customer keeps only what must stay consistent with it
public sealed class Customer
{
    public CustomerId Id { get; init; }
    public string Phone { get; private set; } = "";
    public void ChangePhone(string phone) => Phone = phone;
}
